const Contact = () => (
  <section id="contact" className="py-16 bg-white">
    <div className="container mx-auto text-center">
      <h2 className="text-3xl font-bold mb-4">Contact Me</h2>
      <p className="text-lg mb-4">Email: <a href="mailto:muhammadshahan92@gmail.com">muhammadshahan92@gmail.com</a></p>
      <p className="text-lg">Phone: +92 333-8033929</p>
      <p className="text-lg">LinkedIn: <a href="https://www.linkedin.com/in/muhammad-shahan-152331120/">linkedin.com/in/muhammad-shahan-152331120</a></p>
    </div>
  </section>
);

export default Contact;
